import java.nio.file.*;import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Verify45{public static void main(String[]args)throws Exception{int classes=0,methods=0;for(String p:args)try(ZipFile z=new ZipFile(p)){for(var it=z.entries();it.hasMoreElements();){var e=it.nextElement();if(!e.getName().endsWith(".class")||e.getName().equals("module-info.class"))continue;ClassNode c=new ClassNode();new ClassReader(z.getInputStream(e)).accept(c,0);for(MethodNode m:c.methods)if((m.access&(Opcodes.ACC_ABSTRACT|Opcodes.ACC_NATIVE))==0){try{new Analyzer<>(new BasicVerifier()).analyze(c.name,m);methods++;}catch(Exception ex){throw new IllegalStateException(c.name+"."+m.name+m.desc,ex);}}classes++;}}System.out.println("ASM_BASIC_VERIFIER_CLASSES="+classes+" METHODS="+methods);}}
